"""The recorder for one voice call."""

from __future__ import annotations

import asyncio
import time
from typing import Any

from opentelemetry import trace
from opentelemetry.trace import Span

from rasa.tracing.voice.metrics import (
    AudioDirection,
    CallOutcome,
    record_audio_bytes_metric,
    record_call_duration_metric,
)
from rasa.tracing.voice.shared import semconv
from rasa.tracing.voice.shared.context import CallObservabilityContext


class CallRecorder:
    """Record tracing and metrics for one voice call.

    Args:
        span: Root span for the call. It is non-recording in metrics-only mode.
        observability: Call-scoped state containing the accumulated audio totals.
        emit_metrics: Whether terminal metric emission is enabled.
    """

    def __init__(
        self,
        span: Span,
        observability: CallObservabilityContext,
        *,
        emit_metrics: bool = True,
    ) -> None:
        # Identity and signal state.
        self.span = span
        self._observability_context = observability
        self._emit_metrics = emit_metrics
        # Timing and terminal outcome.
        self._started_monotonic = time.monotonic()
        self._hangup_requested = False
        self._disconnected = False
        self._failed = False
        self._cancelled = False
        # Prevent repeated end() calls from stamping or emitting call totals twice.
        self._ended = False

    @classmethod
    def detached(cls) -> "CallRecorder":
        """Return a recorder that emits neither spans nor metrics."""
        return cls(
            trace.INVALID_SPAN,
            CallObservabilityContext(),
            emit_metrics=False,
        )

    def record_call_started(self) -> None:
        """Record that call setup completed."""
        self._add_event(semconv.EVENT_CALL_STARTED)

    def record_call_ended(self) -> None:
        """Record that active call processing ended."""
        self._add_event(semconv.EVENT_CALL_ENDED)

    def record_disconnect(self) -> None:
        """Record a transport-level disconnect."""
        self._disconnected = True
        self._add_event(semconv.EVENT_DISCONNECT)

    def record_hangup_requested(self) -> None:
        """Record that the agent requested the call to end."""
        self._hangup_requested = True
        self._add_event(semconv.EVENT_HANGUP_REQUESTED)

    def record_failure(self, error: BaseException) -> None:
        """Mark the call as failed while preserving the original exception."""
        self._failed = True
        if self.span.is_recording():
            self.span.set_attribute(semconv.ERROR_TYPE, type(error).__name__)
            self.span.set_status(trace.Status(trace.StatusCode.ERROR))

    def check_and_record_task_failure(self, task: asyncio.Task[Any]) -> None:
        """Record an exception retained by a completed background task."""
        if task.done() and not task.cancelled():
            error = task.exception()
            if error is not None:
                self.record_failure(error)

    def record_cancelled(self) -> None:
        """Record that the call task was cancelled.

        Terminal metrics still emit; cancellation is not a separate outcome.
        """
        self._cancelled = True

    def set_attribute(self, key: str, value: Any) -> None:
        """Set a call-level span attribute."""
        if self.span.is_recording():
            self.span.set_attribute(key, value)

    def end(self) -> None:
        """Stamp call totals and emit terminal metrics once."""
        if self._ended:
            return
        self._ended = True
        if self.span.is_recording():
            self._observability_context.stamp_root_span(self.span)
        if not self._emit_metrics:
            return

        outcome = self._outcome()
        elapsed_s = time.monotonic() - self._started_monotonic
        record_call_duration_metric(elapsed_s, outcome=outcome)
        record_audio_bytes_metric(
            direction=AudioDirection.INPUT,
            audio_bytes=self._observability_context.audio_input_bytes_total,
        )
        record_audio_bytes_metric(
            direction=AudioDirection.OUTPUT,
            audio_bytes=self._observability_context.audio_output_bytes_total,
        )

    def _outcome(self) -> CallOutcome:
        """Resolve the call outcome from its terminal signals."""
        if self._failed:
            return CallOutcome.FAILED
        if self._hangup_requested:
            return CallOutcome.COMPLETED
        if self._disconnected:
            return CallOutcome.DISCONNECTED
        return CallOutcome.COMPLETED

    def _add_event(self, name: str) -> None:
        if self.span.is_recording():
            self.span.add_event(name)
